import { beforeEach, vi } from "vitest";
import { serveStatic, type ServeStaticOptions } from "../src/index.ts";
import { describeMatrix } from "./_setup.ts";

const SIZE = 1000;
const MTIME = 1_700_000_000_000;
const CONTENT = new Uint8Array(SIZE).map((_, i) => i % 256);

function bytesOf(buffer: ArrayBuffer): number[] {
  return [...new Uint8Array(buffer)];
}

describeMatrix("serve static range", (t, { it, expect }) => {
  let options: ServeStaticOptions;

  beforeEach(() => {
    options = {
      getMeta: vi.fn(() => ({
        type: "application/octet-stream",
        etag: '"abc"',
        mtime: MTIME,
        size: SIZE,
      })),
      getContents: vi.fn(() => CONTENT),
    };

    t.app.all("/**", (event) => serveStatic(event, options));
  });

  it("advertises Accept-Ranges on a full response (RF-01)", async () => {
    const res = await t.fetch("/video.bin");

    expect(res.status).toBe(200);
    expect(res.headers.get("accept-ranges")).toBe("bytes");
    expect(res.headers.get("content-length")).toBe(String(SIZE));
    expect(res.headers.get("content-range")).toBeNull();
    expect(bytesOf(await res.arrayBuffer())).toEqual([...CONTENT]);
  });

  it("responds 206 with the requested bytes (RF-02)", async () => {
    const res = await t.fetch("/video.bin", { headers: { range: "bytes=0-499" } });

    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe(`bytes 0-499/${SIZE}`);
    expect(res.headers.get("content-length")).toBe("500");
    expect(res.headers.get("accept-ranges")).toBe("bytes");
    expect(bytesOf(await res.arrayBuffer())).toEqual([...CONTENT.slice(0, 500)]);
  });

  it("accepts open-ended and suffix ranges (RF-03)", async () => {
    for (const range of ["bytes=900-", "bytes=-100"]) {
      const res = await t.fetch("/video.bin", { headers: { range } });

      expect(res.status, range).toBe(206);
      expect(res.headers.get("content-range"), range).toBe(`bytes 900-999/${SIZE}`);
      expect(res.headers.get("content-length"), range).toBe("100");
      expect(bytesOf(await res.arrayBuffer()), range).toEqual([...CONTENT.slice(900)]);
    }
  });

  it("responds 416 for an unsatisfiable range (RF-04)", async () => {
    const res = await t.fetch("/video.bin", { headers: { range: "bytes=2000-3000" } });

    expect(res.status).toBe(416);
    expect(res.headers.get("content-range")).toBe(`bytes */${SIZE}`);
    expect(res.headers.get("content-length")).toBe("0");
    expect(res.headers.get("accept-ranges")).toBe("bytes");
    expect(await res.text()).toBe("");
  });

  it("ignores malformed, multiple or foreign-unit ranges (RF-05)", async () => {
    for (const range of ["bytes=abc", "bytes=0-1,5-9", "items=0-4"]) {
      const res = await t.fetch("/video.bin", { headers: { range } });

      expect(res.status, range).toBe(200);
      expect(res.headers.get("content-range"), range).toBeNull();
      expect(res.headers.get("content-length"), range).toBe(String(SIZE));
      expect(bytesOf(await res.arrayBuffer()), range).toEqual([...CONTENT]);
    }
  });

  it("ignores the range when If-Range does not match (RF-06)", async () => {
    const res = await t.fetch("/video.bin", {
      headers: { range: "bytes=0-99", "if-range": '"xyz"' },
    });

    expect(res.status).toBe(200);
    expect(res.headers.get("content-range")).toBeNull();
    expect(bytesOf(await res.arrayBuffer())).toEqual([...CONTENT]);
  });

  it("applies the range when If-Range matches the strong ETag (RF-06)", async () => {
    const res = await t.fetch("/video.bin", {
      headers: { range: "bytes=0-99", "if-range": '"abc"' },
    });

    expect(res.status).toBe(206);
    expect(bytesOf(await res.arrayBuffer())).toEqual([...CONTENT.slice(0, 100)]);
  });

  it("evaluates cache validators before Range (RF-07)", async () => {
    const res = await t.fetch("/video.bin", {
      headers: { range: "bytes=0-99", "if-none-match": '"abc"' },
    });

    expect(res.status).toBe(304);
    expect(res.headers.get("accept-ranges")).toBeNull();
    expect(res.headers.get("content-range")).toBeNull();
    expect(await res.text()).toBe("");
  });

  it("responds to HEAD with 206 headers and an empty body (RF-08)", async () => {
    const res = await t.fetch("/video.bin", {
      method: "HEAD",
      headers: { range: "bytes=0-499" },
    });

    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe(`bytes 0-499/${SIZE}`);
    expect(res.headers.get("content-length")).toBe("500");
    expect(await res.text()).toBe("");
    expect(options.getContents).not.toHaveBeenCalled();
  });

  it("ignores Range when the asset size is unknown (RF-09)", async () => {
    options.getMeta = vi.fn(() => ({ etag: '"abc"', mtime: MTIME }));
    options.getContents = vi.fn(() => "full body");

    const res = await t.fetch("/video.txt", { headers: { range: "bytes=0-99" } });

    expect(res.status).toBe(200);
    expect(res.headers.get("accept-ranges")).toBe("bytes");
    expect(res.headers.get("content-range")).toBeNull();
    expect(await res.text()).toBe("full body");
  });

  it("applies the range to the chosen precompressed variant (RF-10)", async () => {
    const VARIANT_SIZE = 300;
    const variant = new Uint8Array(VARIANT_SIZE).map((_, i) => (i * 7) % 256);
    options.encodings = { gzip: ".gz" };
    options.getMeta = vi.fn((id) =>
      id === "/app.js.gz" ? { type: "text/javascript", size: VARIANT_SIZE } : undefined,
    );
    options.getContents = vi.fn(() => variant);

    const res = await t.fetch("/app.js", {
      headers: { "accept-encoding": "gzip", range: "bytes=0-9" },
    });

    expect(res.status).toBe(206);
    expect(res.headers.get("content-encoding")).toBe("gzip");
    expect(res.headers.get("content-range")).toBe(`bytes 0-9/${VARIANT_SIZE}`);
    expect(bytesOf(await res.arrayBuffer())).toEqual([...variant.slice(0, 10)]);
  });

  it("keeps 404 for a missing asset even with Range (RF-11)", async () => {
    options.getMeta = vi.fn(() => undefined);

    const res = await t.fetch("/missing.bin", { headers: { range: "bytes=0-99" } });

    expect(res.status).toBe(404);
    expect(res.headers.get("accept-ranges")).toBeNull();
  });

  it("keeps 405 with Allow for unsupported methods even with Range (RF-11)", async () => {
    const res = await t.fetch("/video.bin", {
      method: "POST",
      headers: { range: "bytes=0-99" },
    });

    expect(res.status).toBe(405);
    expect(res.headers.get("allow")).toBe("GET, HEAD");
  });

  it("keeps the full response unchanged apart from Accept-Ranges (RF-11)", async () => {
    const res = await t.fetch("/video.bin");

    expect(res.status).toBe(200);
    expect(res.headers.get("etag")).toBe('"abc"');
    expect(res.headers.get("last-modified")).toBe(new Date(MTIME).toUTCString());
    expect(res.headers.get("content-type")).toBe("application/octet-stream");
  });

  it("overrides a Content-Length set in options.headers on 206", async () => {
    options.headers = { "content-length": "999" };

    const res = await t.fetch("/video.bin", { headers: { range: "bytes=0-9" } });

    expect(res.status).toBe(206);
    expect(res.headers.get("content-length")).toBe("10");
  });

  it("slices string, Blob and ReadableStream bodies on 206", async () => {
    const text = Array.from({ length: SIZE }, (_, i) => String.fromCharCode(97 + (i % 26))).join(
      "",
    );
    const expected = text.slice(0, 500);
    const bodies: Record<string, () => BodyInit> = {
      string: () => text,
      Blob: () => new Blob([text]),
      ReadableStream: () =>
        new ReadableStream<Uint8Array>({
          start(controller) {
            const bytes = new TextEncoder().encode(text);
            for (let i = 0; i < bytes.length; i += 333) {
              controller.enqueue(bytes.slice(i, i + 333));
            }
            controller.close();
          },
        }),
    };

    for (const [kind, makeBody] of Object.entries(bodies)) {
      options.getContents = vi.fn(makeBody);

      const res = await t.fetch("/video.txt", { headers: { range: "bytes=0-499" } });

      expect(res.status, kind).toBe(206);
      expect(res.headers.get("content-length"), kind).toBe("500");
      expect(await res.text(), kind).toBe(expected);
    }
  });

  it("does not read the body on 416", async () => {
    await t.fetch("/video.bin", { headers: { range: "bytes=2000-3000" } });

    expect(options.getContents).not.toHaveBeenCalled();
  });

  it("returns 416 for a range on an empty asset and 200 without Range (size 0)", async () => {
    options.getMeta = vi.fn(() => ({ size: 0 }));
    options.getContents = vi.fn(() => new Uint8Array(0));

    const ranged = await t.fetch("/empty.bin", { headers: { range: "bytes=0-" } });
    expect(ranged.status).toBe(416);
    expect(ranged.headers.get("content-range")).toBe("bytes */0");

    const full = await t.fetch("/empty.bin");
    expect(full.status).toBe(200);
    expect(full.headers.get("content-length")).toBeNull();
    expect(full.headers.get("accept-ranges")).toBe("bytes");
  });
});

